-- 35_rutas_recorrido.sql
-- Recorridos AUTORIZADOS de las rutas (importados de los KMZ oficiales, 22/07/2026).
-- Una polilinea por ruta; puntos = [[lat,lng], ...] (orden Leaflet). Se dibujan
-- en el mapa al filtrar la ruta. Solo lectura para authenticated.

create table if not exists public.rutas_recorrido (
  codigo      text primary key,       -- '133', '133D', ...
  nombre      text,                    -- nombre completo del KMZ
  cod_sonar   text,                    -- codigo oficial (560500, ...)
  puntos      jsonb not null,          -- [[lat,lng], ...]
  actualizado timestamptz not null default now()
);
alter table public.rutas_recorrido enable row level security;
drop policy if exists leer_recorridos on public.rutas_recorrido;
create policy leer_recorridos on public.rutas_recorrido
  for select to authenticated using (true);

